#include "stdlib/blas/base/cdotc.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/base/mul.h"
#include "stdlib/complex/float32/base/add.h"
#include "stdlib/complex/float32/conj.h"
#include <stdint.h>

/**
* Computes the dot product `x^H * y` of two single-precision complex floating-point vectors using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        first input array
* @param strideX  X stride length
* @param offsetX  starting index for X
* @param Y        second input array
* @param strideY  Y stride length
* @param offsetY  starting index for Y
* @return         dot product
*/
stdlib_complex64_t API_SUFFIX(c_cdotc_ndarray)( const CBLAS_INT N, const void *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const void *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	stdlib_complex64_t dot;
	stdlib_complex64_t conjX;
	stdlib_complex64_t xy;
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT i;

	dot = stdlib_complex64_from_float32( 0.0f );
	if ( N <= 0 ) {
		return dot;
	}
	ix = offsetX;
	iy = offsetY;

	stdlib_complex64_t *ip1 = (stdlib_complex64_t *)X;
	stdlib_complex64_t *ip2 = (stdlib_complex64_t *)Y;

	for ( i = 0; i < N; i++ ) {
		conjX = stdlib_complex64_conj( ip1[ ix ] );
		xy = stdlib_base_complex64_mul( conjX, ip2[ iy ] );
		dot = stdlib_base_complex64_add( dot, xy );
		ix += strideX;
		iy += strideY;
	}
	return dot;
}
